// Managed by bedrock. Do not edit in consumer repos: changes arrive through bedrock sync PRs.
//
// Documentation tools shared by every bedrock repo (skill bedrock-docs). No dependencies.
//
//   node .github/bedrock/docs-index.mjs            write the index in docs/README.md
//   node .github/bedrock/docs-index.mjs --check    fail if the index is out of date
//   node .github/bedrock/docs-index.mjs --links    fail on broken relative links in tracked Markdown
//   node .github/bedrock/docs-index.mjs --readme   fail unless README.md and README.it.md link each other
//
// Each doc under docs/ starts with a front matter block:
//   ---
//   title: Architettura          (title in the doc's language)
//   title_en: Architecture        (optional: title in the other language, title_it for English docs)
//   summary: Come è fatto ...     (one line)
//   summary_en: How it is built   (optional, as above)
//   type: explanation             (tutorial | how-to | reference | explanation | decision | record)
//   topic: architecture           (optional: what it covers, see MODULES; several, comma-separated)
//   status: current               (draft | current | outdated)
//   verified: 2026-11-07          (optional: last time it was checked against the code)
//   order: 30                     (optional: position in its section)
//   lang: it                      (optional, default it)
//   ---
// The index groups docs by type, draws a map, and lists the topics that the
// modules declared in .bedrock.yml ("docs: [core, app, ...]") expect but no doc covers yet.
import { execFileSync } from "node:child_process";
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, posix, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";

export const INDEX_BEGIN =
  "<!-- bedrock:docs-index:begin: generated by .github/bedrock/docs-index.mjs, do not edit by hand -->";
export const INDEX_END = "<!-- bedrock:docs-index:end -->";

// In reading order: the map draws an arrow from each group to the next.
export const TYPES = [
  ["tutorial", "Imparare", "Learn"],
  ["explanation", "Capire", "Explanation"],
  ["how-to", "Fare", "How-to"],
  ["reference", "Consultare", "Reference"],
  ["decision", "Decisioni", "Decisions"],
  ["record", "Diario e risultati", "Records and results"],
];

// Topics each docs module expects. A doc covers a topic with "topic: <id>" in its
// front matter; decisions are covered by any doc of type "decision".
export const MODULES = {
  core: [
    ["vision", "Visione e perimetro", "Vision and scope"],
    ["architecture", "Architettura", "Architecture"],
    ["verification", "Verificato e non verificato", "Verified and not verified"],
    ["decisions", "Decisioni", "Decisions"],
  ],
  app: [
    ["ux", "Esperienza d'uso", "User experience"],
    ["user-guide", "Guida per chi lo usa", "User guide"],
  ],
  hardware: [
    ["hardware-tests", "Prove sull'hardware", "Hardware tests"],
    ["protocol", "Riferimenti del protocollo", "Protocol references"],
  ],
  product: [
    ["market", "Mercato e utenti", "Market and users"],
    ["mvp", "Prodotto minimo", "Minimum viable product"],
  ],
  site: [
    ["editorial-guide", "Guida per la redazione", "Editorial guide"],
    ["content-model", "Modello dei contenuti", "Content model"],
  ],
  kit: [
    ["reference", "Riferimento", "Reference"],
    ["how-to", "Guide pratiche", "How-to guides"],
  ],
  analysis: [
    ["method", "Metodo", "Method"],
    ["data-sources", "Fonti dei dati", "Data sources"],
    ["limits", "Limiti e avvertenze", "Limits and disclaimers"],
  ],
};

// Bigger groups are drawn as one node, so the map stays readable.
const MAP_MAX_PER_GROUP = 5;

const STATUS = {
  draft: "bozza · draft",
  current: "attuale · current",
  outdated: "da aggiornare · outdated",
};

/** Parses the front matter at the top of a Markdown file (simple `key: value` lines). */
export function parseFrontMatter(text) {
  // A UTF-8 BOM (Windows PowerShell 5 writes one) must not hide the front matter.
  const t = text.replace(/^﻿/, "").replace(/\r\n/g, "\n");
  if (!t.startsWith("---\n")) return null;
  // The closing fence is a line that is exactly "---" (not "----").
  const close = /\n---[ \t]*(?:\n|$)/.exec(t.slice(3));
  if (!close) return null;
  const end = close.index + 3;
  const data = {};
  for (const line of t.slice(4, end).split("\n")) {
    const m = /^([A-Za-z_][\w-]*):\s*(.*)$/.exec(line);
    if (!m) continue;
    let value = m[2].trim();
    if (/^(["']).*\1$/.test(value)) value = value.slice(1, -1);
    data[m[1]] = value;
  }
  return data;
}

/** Reads `docs:` and `design:` from .bedrock.yml (inline list or block list). */
export function readDocsConfig(root) {
  const path = join(root, ".bedrock.yml");
  if (!existsSync(path)) return { declared: false, modules: [], design: undefined };
  const lines = readFileSync(path, "utf8").replace(/\r\n/g, "\n").split("\n");
  let modules = [];
  let design;
  let declared = false;
  const unquote = (s) => s.trim().replace(/^(["'])(.*)\1$/, "$2");
  for (let i = 0; i < lines.length; i++) {
    const docs = /^docs:\s*(.*)$/.exec(lines[i]);
    if (docs) {
      declared = true;
      const inline = docs[1].replace(/\s#.*$/, "").trim();
      if (inline.startsWith("[")) {
        // docs: [core, "app"]
        modules = inline
          .replace(/^\[|\]$/g, "")
          .split(",")
          .map(unquote)
          .filter(Boolean);
      } else if (inline !== "") {
        // docs: core
        modules = [unquote(inline)];
      } else {
        // docs:\n  - core   (indented or not)
        for (let j = i + 1; j < lines.length && /^\s*-\s+/.test(lines[j]); j++) {
          modules.push(unquote(lines[j].replace(/^\s*-\s+/, "").replace(/\s#.*$/, "")));
        }
      }
    }
    const d = /^design:\s*(.*)$/.exec(lines[i]);
    if (d) {
      const v = d[1]
        .replace(/\s#.*$/, "")
        .trim()
        .replace(/^(["'])(.*)\1$/, "$2");
      if (v && v !== "null" && v !== "~") design = v;
    }
  }
  return { declared, modules, design };
}

function walk(dir) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir)
    .sort()
    .flatMap((name) => {
      const p = join(dir, name);
      if (statSync(p).isDirectory()) return name === "node_modules" ? [] : walk(p);
      return name.endsWith(".md") ? [p] : [];
    });
}

const toPosix = (p) => p.split(sep).join("/");
const cell = (s) =>
  String(s ?? "")
    .replace(/\|/g, "\\|")
    .replace(/\n/g, " ");
const mermaidText = (s) =>
  String(s)
    .replace(/[#`;]/g, " ")
    .replace(/"/g, "#quot;")
    .replace(/[[\]{}()<>]/g, " ");

// Link text and targets in the generated tables: brackets escaped, spaces encoded.
const linkText = (s) => cell(s).replace(/([[\]])/g, "\\$1");
const linkPath = (p) => p.split("/").map(encodeURIComponent).join("/");
const complete = (meta) => Boolean(meta?.title && meta?.summary && meta?.type);

/** Collects the docs under docs/ (except docs/README.md) with their front matter. */
export function collectDocs(root) {
  const docsDir = join(root, "docs");
  return walk(docsDir)
    .map((file) => ({
      path: toPosix(relative(docsDir, file)),
      meta: parseFrontMatter(readFileSync(file, "utf8")),
    }))
    .filter((d) => d.path !== "README.md");
}

function titles(meta) {
  const lang = meta.lang === "en" ? "en" : "it";
  const other = lang === "it" ? "en" : "it";
  return {
    title: meta.title,
    titleOther: meta[`title_${other}`],
    summary: meta.summary,
    summaryOther: meta[`summary_${other}`],
  };
}

/** Renders the generated block of docs/README.md. */
export function renderIndex({ docs, modules, design }) {
  const withMeta = docs.filter((d) => complete(d.meta));
  const without = docs.filter((d) => !complete(d.meta));
  const known = new Set(TYPES.map(([t]) => t));
  const byType = TYPES.map(([type, it, en]) => ({
    type,
    it,
    en,
    docs: withMeta
      .filter((d) => d.meta.type === type)
      .sort(
        (a, b) =>
          Number(a.meta.order ?? 1000) - Number(b.meta.order ?? 1000) ||
          a.path.localeCompare(b.path),
      ),
  })).filter((g) => g.docs.length > 0);
  const unknownType = withMeta.filter((d) => !known.has(d.meta.type));

  const out = [INDEX_BEGIN, ""];
  if (byType.length > 0) {
    out.push(
      "## Mappa · Map",
      "",
      "Ordine di lettura consigliato · Suggested reading order.",
      "",
      "```mermaid",
      "flowchart LR",
    );
    if (design) out.push(`  design[["Design<br/>${mermaidText(design)}"]]`);
    let n = 0;
    for (const g of byType) {
      out.push(`  subgraph ${g.type.replace(/-/g, "_")}["${g.it} · ${g.en}"]`);
      if (g.docs.length > MAP_MAX_PER_GROUP) {
        out.push(`    d${n++}["${g.docs.length} documenti · documents"]`);
        out.push("  end");
        continue;
      }
      for (const d of g.docs) {
        const t = titles(d.meta);
        out.push(
          `    d${n++}["${mermaidText(t.title)}${t.titleOther ? `<br/><i>${mermaidText(t.titleOther)}</i>` : ""}"]`,
        );
      }
      out.push("  end");
    }
    const ids = byType.map((g) => g.type.replace(/-/g, "_"));
    for (let i = 1; i < ids.length; i++) out.push(`  ${ids[i - 1]} --> ${ids[i]}`);
    out.push("```", "");
  }
  if (design) {
    out.push(
      `**Riferimento di design · Design reference:** [${linkText(design)}](${linkPath(posix.relative("docs", design))})`,
      "",
    );
  }
  for (const g of byType) {
    out.push(
      `## ${g.it} · ${g.en}`,
      "",
      "| Documento · Document | In breve · In short | Stato · Status | Verificato · Verified |",
      "|---|---|---|---|",
    );
    for (const d of g.docs) {
      const t = titles(d.meta);
      const title = `[${linkText(t.title)}](${linkPath(d.path)})${t.titleOther ? `<br/><sub>${cell(t.titleOther)}</sub>` : ""}`;
      const summary = `${cell(t.summary)}${t.summaryOther ? `<br/><sub>${cell(t.summaryOther)}</sub>` : ""}`;
      out.push(
        `| ${title} | ${summary} | ${STATUS[d.meta.status] ?? cell(d.meta.status ?? "—")} | ${cell(d.meta.verified ?? "—")} |`,
      );
    }
    out.push("");
  }
  if (unknownType.length > 0) {
    out.push("## Tipo sconosciuto · Unknown type", "");
    for (const d of unknownType)
      out.push(`- [${linkText(d.meta.title)}](${linkPath(d.path)}): \`type: ${d.meta.type}\``);
    out.push("");
  }
  if (without.length > 0) {
    out.push(
      "## Senza intestazione · No front matter",
      "",
      "Aggiungi `title`, `summary` e `type` (skill `bedrock-docs`). · Add `title`, `summary` and `type`.",
      "",
    );
    for (const d of without) {
      const note = d.meta
        ? ": manca `title`, `summary` o `type` · missing title, summary or type"
        : "";
      out.push(`- [${linkText(d.path)}](${linkPath(d.path)})${note}`);
    }
    out.push("");
  }
  const topics = new Set(
    withMeta.flatMap((d) => (d.meta.topic ?? "").split(",").map((t) => t.trim())).filter(Boolean),
  );
  if (withMeta.some((d) => d.meta.type === "decision")) topics.add("decisions");
  const missing = modules.flatMap((m) =>
    (MODULES[m] ?? []).filter(([id]) => !topics.has(id)).map((t) => [m, ...t]),
  );
  const unknownModules = modules.filter((m) => !(m in MODULES));
  if (missing.length > 0 || unknownModules.length > 0) {
    out.push("## Da scrivere · To write", "");
    for (const [m, id, it, en] of missing)
      out.push(`- ${it} · ${en} (\`topic: ${id}\`, modulo · module \`${m}\`)`);
    for (const m of unknownModules) out.push(`- Modulo sconosciuto · Unknown module \`${m}\``);
    out.push("");
  }
  out.push(INDEX_END);
  return `${out.join("\n")}\n`;
}

/** Inserts or replaces the generated block in docs/README.md text. */
export function upsertIndex(existing, block) {
  if (existing === null) {
    return `# Documentazione · Documentation\n\n${block}`;
  }
  const t = existing.replace(/\r\n/g, "\n");
  const b = t.indexOf(INDEX_BEGIN);
  const e = t.indexOf(INDEX_END);
  if (b !== -1 && e > b) {
    let after = t.slice(e + INDEX_END.length);
    if (after.startsWith("\n")) after = after.slice(1);
    return t.slice(0, b) + block + after;
  }
  if (b !== -1 || e !== -1) throw new Error("docs index markers are unbalanced in docs/README.md");
  return t.replace(/\n*$/, "\n\n") + block;
}

export function buildIndex(root) {
  const { modules, design } = readDocsConfig(root);
  const path = join(root, "docs", "README.md");
  const existing = existsSync(path) ? readFileSync(path, "utf8") : null;
  return {
    path,
    existing,
    next: upsertIndex(existing, renderIndex({ docs: collectDocs(root), modules, design })),
  };
}

function trackedMarkdown(root) {
  try {
    return execFileSync("git", ["ls-files", "-z", "--", "*.md"], { cwd: root, encoding: "utf8" })
      .split("\0")
      .filter(Boolean);
  } catch {
    return walk(root).map((p) => toPosix(relative(root, p)));
  }
}

/** The Markdown text without code (fenced and inline) and HTML comments. */
export function proseOnly(text) {
  const out = [];
  let fence = null;
  for (const line of text.replace(/^﻿/, "").replace(/\r\n/g, "\n").split("\n")) {
    const open = /^\s{0,3}(`{3,}|~{3,})/.exec(line);
    if (fence) {
      // A fence closes only with the same character, at least as long, and nothing else.
      const close = /^\s{0,3}(`{3,}|~{3,})\s*$/.exec(line);
      if (close && close[1][0] === fence[0] && close[1].length >= fence.length) fence = null;
      out.push("");
      continue;
    }
    if (open) {
      fence = open[1];
      out.push("");
      continue;
    }
    out.push(line.replace(/(`+)[^`][\s\S]*?\1/g, "").replace(/(`+)\1/g, ""));
  }
  return out.join("\n").replace(/<!--[\s\S]*?-->/g, "");
}

/** Relative and absolute link targets in Markdown prose (links, images, references, HTML). */
export function linkTargets(text) {
  const prose = proseOnly(text);
  const targets = [];
  // Inline links and images: every "](" opens a target, so "[![a](i.png)](b.md)" gives both.
  for (let i = prose.indexOf("]("); i !== -1; i = prose.indexOf("](", i + 2)) {
    let j = i + 2;
    while (prose[j] === " ") j++;
    let target = "";
    if (prose[j] === "<") {
      const end = prose.indexOf(">", j);
      if (end !== -1) target = prose.slice(j, end + 1);
    } else {
      let depth = 0;
      let k = j;
      for (; k < prose.length; k++) {
        const c = prose[k];
        if (c === "\\") {
          k++;
        } else if (c === "(") {
          depth++;
        } else if (c === ")") {
          if (depth === 0) break;
          depth--;
        } else if (/\s/.test(c)) {
          break;
        }
      }
      target = prose.slice(j, k);
    }
    if (target) targets.push(target);
  }
  // Reference definitions, but not footnotes ("[^1]: text").
  for (const m of prose.matchAll(/^\s{0,3}\[(?!\^)[^\]]+\]:\s*(<[^>]+>|\S+)/gm)) targets.push(m[1]);
  for (const m of prose.matchAll(
    /<(?:img|a|source)\s[^>]*?(?:src|href|srcset)=["']([^"']+)["']/g,
  )) {
    for (const part of m[1].split(",")) {
      const t = part.trim().split(/\s+/)[0];
      if (t) targets.push(t);
    }
  }
  return targets;
}

/** Tracked files and their folders, exactly as git (and GitHub) see them; null without git. */
function trackedPaths(root) {
  try {
    const files = execFileSync("git", ["ls-files", "-z"], { cwd: root, encoding: "utf8" })
      .split("\0")
      .filter(Boolean);
    const set = new Set(files);
    for (const f of files) {
      for (let d = posix.dirname(f); d !== "." && !set.has(`${d}/`); d = posix.dirname(d))
        set.add(`${d}/`);
    }
    return set;
  } catch {
    return null;
  }
}

/** Returns "file: target" for every relative link that does not resolve. */
export function brokenLinks(root) {
  const broken = [];
  const tracked = trackedPaths(root);
  const top = resolve(root);
  for (const file of trackedMarkdown(root)) {
    const abs = join(root, file);
    if (!existsSync(abs)) continue;
    for (let target of linkTargets(readFileSync(abs, "utf8"))) {
      if (target.startsWith("<")) target = target.slice(1, -1);
      if (/^(?:[a-z][a-z0-9+.-]*:|#|\/\/)/i.test(target)) continue;
      let path = target.split("#")[0].split("?")[0];
      if (path === "") continue;
      try {
        path = decodeURIComponent(path);
      } catch {
        /* keep as written */
      }
      const resolved = resolve(path.startsWith("/") ? join(root, path) : join(dirname(abs), path));
      if (resolved !== top && !resolved.startsWith(top + sep)) {
        broken.push(`${file}: ${target} (outside the repo: it breaks on GitHub)`);
        continue;
      }
      const rel = toPosix(relative(top, resolved));
      // Compared with git's list: exact case (GitHub is case-sensitive) and tracked files only.
      const ok = tracked
        ? rel === "" || tracked.has(rel) || tracked.has(`${rel.replace(/\/$/, "")}/`)
        : existsSync(resolved);
      if (!ok)
        broken.push(
          `${file}: ${target}${tracked && existsSync(resolved) ? " (not tracked by git, or different case)" : ""}`,
        );
    }
  }
  return broken;
}

/** Problems with the bilingual README pair (empty list = fine). */
export function readmeProblems(root) {
  const problems = [];
  const en = join(root, "README.md");
  const it = join(root, "README.it.md");
  if (!existsSync(en)) problems.push("README.md is missing");
  if (!existsSync(it)) problems.push("README.it.md (Italian) is missing");
  if (problems.length > 0) return problems;
  const enText = readFileSync(en, "utf8");
  const itText = readFileSync(it, "utf8");
  if (!/^#\s+\S/m.test(enText)) problems.push("README.md has no title (# ...)");
  if (!/^#\s+\S/m.test(itText)) problems.push("README.it.md has no title (# ...)");
  if (!/\]\(\.?\/?README\.it\.md\)/.test(enText))
    problems.push("README.md does not link to README.it.md");
  if (!/\]\(\.?\/?README\.md\)/.test(itText))
    problems.push("README.it.md does not link to README.md");
  const h2 = (t) => (proseOnly(t).match(/^##\s+/gm) ?? []).length;
  if (h2(enText) !== h2(itText))
    problems.push(
      `README.md has ${h2(enText)} sections (##) and README.it.md has ${h2(itText)}: keep them in step`,
    );
  return problems;
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  let args = process.argv.slice(2);
  // --root <dir>: the repo to work on (default: the current folder), for callers that cannot cd.
  const at = args.indexOf("--root");
  if (at >= 0 && (!args[at + 1] || args[at + 1].startsWith("--"))) {
    console.log("::error::--root needs a folder");
    process.exit(2);
  }
  const root = at >= 0 ? resolve(args[at + 1]) : process.cwd();
  if (at >= 0) args = args.filter((_, i) => i !== at && i !== at + 1);
  const unknown = args.filter((a) => !["--links", "--readme", "--check"].includes(a));
  if (unknown.length > 0) {
    console.log(
      `::error::unknown option ${unknown.join(" ")} (use --check, --links, --readme, --root <dir>, or none to write the index)`,
    );
    process.exit(2);
  }
  let failed = false;
  if (args.includes("--links")) {
    const broken = brokenLinks(root);
    for (const b of broken) console.log(`::error::broken link: ${b}`);
    failed ||= broken.length > 0;
    if (broken.length === 0) console.log("all relative Markdown links resolve");
  }
  const { declared } = readDocsConfig(root);
  const optIn = (what) => {
    if (declared) return true;
    console.log(
      `${what}: skipped, this repo has not adopted bedrock-docs yet (no "docs:" in .bedrock.yml)`,
    );
    return false;
  };
  if (args.includes("--readme") && optIn("README check")) {
    const problems = readmeProblems(root);
    for (const p of problems) console.log(`::error::${p}`);
    failed ||= problems.length > 0;
    if (problems.length === 0) console.log("README.md and README.it.md are in step");
  }
  if (args.includes("--check") && optIn("docs index check")) {
    const { existing, next } = buildIndex(root);
    if (existing?.replace(/\r\n/g, "\n") !== next) {
      console.log(
        "::error file=docs/README.md::the docs index is out of date: run node .github/bedrock/docs-index.mjs and commit",
      );
      failed = true;
    } else {
      console.log("docs index is up to date");
    }
    const incomplete = collectDocs(root).filter((d) => !complete(d.meta));
    for (const d of incomplete) {
      console.log(
        `::error file=docs/${d.path}::front matter needs title, summary and type (skill bedrock-docs)`,
      );
    }
    failed ||= incomplete.length > 0;
  }
  if (!args.some((a) => ["--links", "--readme", "--check"].includes(a))) {
    const { path, existing, next } = buildIndex(root);
    if (existing?.replace(/\r\n/g, "\n") === next) console.log("docs/README.md is up to date");
    else {
      writeFileSync(path, next);
      console.log("wrote docs/README.md");
    }
  }
  if (failed) process.exit(1);
}
